package mod.cdv.tnpc.tactical;
import java.util.*;
public final class Downed20 {
 static final Map<Object,Rescue> RESCUES=new WeakHashMap<>();static boolean down(Object n){return Social.yes(Social.c(Social.tag(n),"getBoolean","soc_down20"));}
 public static boolean blockDeath(Object n,Object source){if(!Social.actor(n)||Social.client(n))return false;Object tag=Social.tag(n);String reason=(String)Social.c(source,"getMsgId");if(Social.yes(Social.c(tag,"getBoolean","soc_final20"))||reason.equals("outOfWorld")||reason.equals("genericKill"))return false;long now=Social.time(n);if(down(n)){if(now<Social.l(tag,"soc_down_grace20")){Social.c(n,"setHealth",1f);return true;}return false;}try{Social.init(n);Social.c(tag,"putBoolean","soc_down20",true);Social.c(tag,"putLong","soc_down_until20",now+2000);Social.c(tag,"putLong","soc_down_grace20",now+20);Social.c(n,"setHealth",1f);Social.c(n,"setNoAi",true);Social.target(n,null);Social.c(Social.c(n,"getNavigation"),"stop");Social.c(n,"setPose",SocialR.get(Social.t("net.minecraft.world.entity.Pose"),"SWIMMING"));Social.mem(n).occupied=true;Social.mem(n).medicalUntil=0;NpcMedicine.TREATMENTS.remove(n);CalmLoot.release(n,CalmBrain.state(n));Expression20.MOTIONS.remove(n);NpcClinic20.changed(n);Expression20.chat(n,"wounded",null,false);return true;}catch(Exception e){Social.warn("NPC downed",e);return false;}}
 public static void tick(Object n)throws Exception{long now=Social.time(n);Social.c(Social.c(n,"getNavigation"),"stop");Social.c(n,"setPose",SocialR.get(Social.t("net.minecraft.world.entity.Pose"),"SWIMMING"));Social.mem(n).occupied=true;Rescue r=RESCUES.get(n);if(r!=null){if(!Social.alive(r.player)||Social.world(n)!=Social.world(r.player)||Social.distance(n,r.player)>9||!Social.visible(n,r.player)||(r.stack!=null&&(Social.c(r.player,"getMainHandItem")!=r.stack&&Social.c(r.player,"getOffhandItem")!=r.stack||CalmLoot.empty(r.stack)))){RESCUES.remove(n);NpcClinic20.send(n,r.player);return;}if(now-r.start>=r.duration){RESCUES.remove(n);if(r.stack!=null){int damage=((Number)Social.c(r.stack,"getDamageValue")).intValue()+1;if(damage>=5)Social.c(r.stack,"shrink",1);else{Social.c(r.stack,"set",SocialR.get(Social.t("net.minecraft.core.component.DataComponents"),"MAX_DAMAGE"),5);Social.c(r.stack,"setDamageValue",damage);}}revive(n,r.player);NpcClinic20.send(n,r.player);return;}if(now%10==0)NpcClinic20.send(n,r.player);}
  if(now>=Social.l(Social.tag(n),"soc_down_until20")){Social.c(Social.tag(n),"putBoolean","soc_final20",true);Object source=Social.c(Social.c(n,"damageSources"),"genericKill");Social.c(n,"die",source);}}
 static boolean begin(Object n,Object p){if(!down(n)||RESCUES.containsKey(n)||Social.distance(n,p)>9||!Social.visible(n,p))return false;Object defib=null;for(String hand:new String[]{"getMainHandItem","getOffhandItem"}){Object stack=Social.c(p,hand);if(NpcMedicine.defib(stack)){defib=stack;break;}}RESCUES.put(n,new Rescue(p,defib,Social.time(n),defib==null?160:60));NpcClinic20.send(n,p);return true;}
 static void revive(Object n,Object p){Social.c(Social.tag(n),"putBoolean","soc_down20",false);Social.c(Social.tag(n),"putLong","soc_down_until20",0L);Social.c(n,"setNoAi",false);Social.c(n,"setPose",SocialR.get(Social.t("net.minecraft.world.entity.Pose"),"STANDING"));Social.c(n,"setShiftKeyDown",false);Social.c(n,"setHealth",(float)Math.max(1,Social.num(Social.c(n,"getMaxHealth"))*.3));NpcMedicine.init(n);for(String key:NpcClinic20.KEYS){double max=Social.num(Social.c(Social.tag(n),"getDouble","np15_max_"+key));double hp=Social.num(Social.c(Social.tag(n),"getDouble","np15_hp_"+key));Social.c(Social.tag(n),"putDouble","np15_hp_"+key,Math.max(hp,max*.25));}Social.mem(n).occupied=false;Social.mem(n).medicalUntil=0;Social.trust(n,p,12);Social.ledger("change",Social.server(n),Social.identity(p),3);Expression20.react(n,p,"treated");}
 record Rescue(Object player,Object stack,long start,int duration){}
}
